sect1.programlisting:
GError *error = NULL;
GswManager *manager = gsw_manager_new_for_path("~/.sword", &error);
GswModule *module = gsw_manager_get_module(manager, "KJV");

gsw_module_set_key_text(module, "John 3:16", &error);
gchar *text = gsw_module_get_text(module, &error);
g_print("%s\n", text);
